        "localizador": "L06"
      },
      {
        "fonte_id": "f_8ca6cc3cb4",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_6c35e786bd",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
